// Every spoken line in the game. Single source of truth for subtitles AND
// for voice generation (scripts/generate-voices.mjs reads this file).
// [bracketed] tags are ElevenLabs v4 performance directions: they are sent to
// the voice model but stripped from on-screen subtitles. [pause] marks the
// beats where Alan stops joking.
window.LINES = {
  // ================================================================ CHAPTER I: THE FOG
  narr_ch1_card: ['narr', "Chapter One. The Fog. Eleven o'clock, on the ninth day."],
  narr_intro_1: ['narr', "For nine days the fog had sat on Lisbon like a cat on a warm book. Nobody could move it, and nobody quite liked to try."],
  narr_intro_2: ['narr', "Three people had drowned in their beds, half a mile uphill from the river, and the trams went on ringing for no one."],
  narr_intro_3: ['narr', "In a crooked bookshop in the Alfama, the one man in the city who most needed to be awake... was asleep."],
  ines_wake: ['ines', "It's eleven, Alan. Even the cat has done more today."],
  alan_wake: ['alan', "[groggy] I'm thirty-seven, Inês. At my age you don't wake up. You resurface."],
  ines_intro_2: ['ines', "Your answering machine has been blinking at me all morning. Either it's a creditor or a woman. Either way, listen to it."],

  // Inês keeps score of his jokes
  ines_score_1: ['ines', "Four out of ten. The cat laughed."],
  ines_score_2: ['ines', "Six. You're improving. Slowly. Like the tide."],
  ines_score_3: ['ines', "Two out of ten, and one of those is for effort."],
  ines_score_4: ['ines', "[dry] Seven. Don't let it go to your head; there's nothing up there to stop it."],
  ines_score_5: ['ines', "Three. Your grandfather told that one better in nineteen sixty."],
  ines_score_6: ['ines', "Five out of ten. Halfway to funny. Halfway to anything, really."],
  ines_score_7: ['ines', "[sighs] One. And I'm being generous because it's foggy."],
  ines_score_8: ['ines', "Eight! Write it down. It won't happen again."],
  ines_score_9: ['ines', "Zero, Alan. The cat left the room."],
  ines_score_10: ['ines', "Six and a half. The half is for timing. The six is pity."],

  // ---------- Bookshop ----------
  narr_look_shelves: ['narr', "Livraria Sanchez. Four thousand second-hand books, sorted by a system known only to the late Joaquim Sanches, and to no one since."],
  narr_look_window: ['narr', "Fog presses against the glass like something that wants to come in. The tram bells sound muffled, and very far away."],
  narr_look_magnifier: ['narr', "A brass magnifying glass on the window shelf, for examining watermarks, bindings, and the occasional splinter."],
  alan_take_magnifier: ['alan', "For the small print. In this family, it's all small print."],
  narr_look_press: ['narr', "A bookbinding press, clamping a Camões that nobody has bought since nineteen seventy-two, weighed down with a two-kilo brass weight."],
  alan_take_weight: ['alan', "Every adventurer should carry a dead weight. Inês carries me."],
  alan_camoes: ['alan', "Camões. The greatest poet in the language. Nobody buys him either. We have an understanding."],
  narr_look_kettle: ['narr', "A kettle, a jar of instant coffee, and two chipped mugs. One of them says 'world's okayest grandson'."],
  alan_look_pessoa: ['alan', "Pessoa. Named after a poet with seventy personalities. This one has one, and it's asleep."],
  alan_look_pessoa_desk: ['alan', "He's asleep on the desk, under the lamp, right on top of the lock. Of all the places in Lisbon."],
  alan_take_pessoa: ['alan', "Nine kilos of no."],
  alan_talk_pessoa: ['alan', "Pessoa. Buddy. I need the desk. [pause] He's pretending to be a rug. Badly."],
  alan_push_pessoa: ['alan', "He's gone boneless. It's the only martial art a cat needs."],
  narr_look_lamp_banker: ['narr', "Grandfather's green banker's lamp. It has burned over his desk since the funeral. Nobody had the heart to switch it off, and the cat has made the most of it."],
  alan_lamp_off: ['alan', "No warmth, no company. He's like every relationship I've had."],
  alan_lamp_again: ['alan', "I'll leave it off. He's earned the radiator, and I've earned the desk."],
  narr_look_radiator: ['narr', "A cast-iron radiator that clanks like a ghost with a grievance. It is the warmest thing in the shop, Alan included."],
  alan_look_pessoa_radiator: ['alan', "He's moved to the radiator. Loyal to the heat, not the man."],
  narr_look_desk: ['narr', "Grandfather's desk. The drawer has been locked since his funeral, and Alan has never found the key."],
  alan_desk_cat: ['alan', "Pessoa's asleep on the lock. I'd have to unlock him first."],
  alan_drawer_locked: ['alan', "Locked. Grandfather took his secrets seriously. And apparently the key, too."],
  narr_look_tin: ['narr', "A battered tin on the shelf above the kettle, marked 'açúcar'. Sugar."],
  alan_sugar_tin: ['alan', "Grandfather kept his key in the sugar. Sweet man. Suspicious, but sweet."],
  alan_unlock: ['alan', "Click. Grandfather's drawer, open for the first time since the funeral."],
  alan_take_ledger: ['alan', "Grandfather kept the books. I just sell them. Neither of us ever balanced."],
  alan_drawer_empty: ['alan', "Empty, apart from forty years of pencil shavings and one very old peppermint."],
  alan_look_register: ['alan', "Three coins. My entire liquid assets. Liquid being the word, in this weather."],
  alan_take_coins: ['alan', "Petty cash. Petty, but loyal."],
  alan_register_empty: ['alan', "Just the button now. I'm keeping the button for emergencies."],
  narr_look_machine: ['narr', "An answering machine of the kind sold by men in airports. The red light blinks with quiet insistence."],
  rui_msg_1: ['rui', "[tired] Alan, it's Rui. Mendonça. I know you're there, you never answer. Listen... there's been another one. It's your kind of weird. Come down to the Judiciária. And Alan, bring your head, not your jokes."],
  narr_msg_2: ['narr', "Message two. Eight seconds of dripping water. Then a click."],
  alan_hangup: ['alan', "Wrong number. Or a very sad plumber."],
  alan_after_msg: ['alan', "Rui Mendonça asking me for help. The fog really has gotten to people."],
  alan_machine_again: ['alan', "No new messages. Even my creditors have given up."],
  narr_look_phone: ['narr', "A black telephone with a cord that has been untangled exactly once, in nineteen sixty-eight."],
  alan_phone_ch1: ['alan', "I could ring Rui back. But then he'd know I listen to my messages."],
  narr_look_news: ['narr', "The Diário de Notícias. 'Third dry drowning in Lisbon. Victim found in a locked bedroom, lungs full of seawater. Police baffled.'"],
  alan_news: ['alan', "Seawater. Half a mile uphill from the river. That's not a drowning, that's a magic trick."],
  narr_look_ines: ['narr', "Inês Carvalho: historian, part-time assistant, full-time conscience. She is writing a thesis that is better than anything Alan has ever written."],
  alan_door_first: ['alan', "The machine first. Somebody wants me, and it's been a while."],
  narr_look_counter: ['narr', "The counter, where Alan does most of his sleeping and some of his selling."],

  // Inês
  ines_hello: ['ines', "If you're going to stand there, at least stand there helpfully."],
  alan_ask_ines_work: ['alan', "What are you working on?"],
  ines_work: ['ines', "My thesis. Seventeen fifty-five. The earthquake, the fire, the wave. Lisbon died three times in one morning, Alan. All Saints' Day. The churches were full."],
  alan_ask_ines_grandpa: ['alan', "Did my grandfather ever talk to you about bells?"],
  ines_grandpa: ['ines', "He talked to me about everything except bells. He went quiet whenever the cathedral rang the hour. I thought it was grief."],
  alan_ask_ines_now: ['alan', "What now?"],
  alan_show_sketch: ['alan', "The police found this tile at every murder scene. Mean anything to you?"],
  ines_sketch_1: ['ines', "A bell beneath the waves... Alan, that's the seal of the Irmandade do Sino Afogado. The Brotherhood of the Drowned Bell."],
  ines_sketch_2: ['ines', "Eighteenth-century fanatics. The legend says they rang a bell beneath the city on the morning of the earthquake... and the river answered."],
  ines_sketch_founders: ['ines', "They paid four families of bell-founders to cast it. Ferreira, Bastos, Coutinho... and Sanches. Alan. Those are the names on your list."],
  alan_founders: ['alan', "Bell-founders. So that's the family business. And I've been foundering in a bookshop."],
  ines_monster: ['ines', "And that sea monster on your street is holding the same bell. You walk past it every day. Well. Every afternoon."],
  ines_sketch_3: ['ines', "There was a fado about it. 'O Sino Afogado.' Nobody sings it anymore. But your grandfather drank at the Taberna da Saudade for fifty years, and Dona Amália still sings there."],
  ines_bye: ['ines', "Go on. I'll mind the shop. Someone has to."],

  // ---------- Street ----------
  narr_look_street: ['narr', "The Alfama: a tangle of stairways and laundry lines, where the fog drifts between the houses like a slow grey river."],
  narr_look_tram: ['narr', "The stop for Tram 28. The yellow trams still run, bells clanging through the murk, carrying passengers who can't see where they're going."],
  narr_look_tavern_door: ['narr', "A Taberna da Saudade. Fado every night, and most afternoons, whether you like it or not."],
  narr_look_azulejo: ['narr', "Old blue tiles line the walls: saints, ships, and a faded sea monster with a strangely knowing expression."],
  alan_look_monster: ['alan', "It has a knowing look. It's seen me before eleven, which almost nobody has."],
  alan_mag_monster: ['alan', "It's holding a bell. Everyone in this city is ringing something except me."],
  narr_look_lamp: ['narr', "A street lamp, burning at noon. Nobody has bothered to switch them off since the fog came."],
  alan_tavern_shut: ['alan', "Fado at noon, on an empty stomach? Not without a reason. I'll find one."],

  // ---------- Polícia Judiciária ----------
  narr_look_board: ['narr', "A corkboard of photographs. Three bedrooms, three bodies, and three small shards of blue tile laid neatly on three pillows."],
  narr_look_evidence: ['narr', "An evidence bag holding a fragment of azulejo: a bronze bell, painted beneath curling blue waves."],
  rui_hands_off: ['rui', "Hands off my evidence, Alan. Talk to me first."],
  alan_sketch: ['alan', "I can't take the evidence, but I can take a likeness. Story of my romantic life."],
  alan_have_sketch: ['alan', "I've already drawn it. A second one won't make me a better artist."],
  narr_look_rui: ['narr', "Inspector Rui Mendonça of the Polícia Judiciária. Twenty years of murders have worn him down to coffee, cigarettes and a moustache."],
  narr_look_cabinet: ['narr', "A filing cabinet. The bottom drawer stands an inch open, as if it were listening."],
  alan_drawer_ch1: ['alan', "Stuck. Not open, not shut. Like me at parties."],
  narr_look_coffee: ['narr', "Coffee, of a sort. Thick enough to stand a spoon in, and Rui has."],
  narr_look_machine_coffee: ['narr', "A coffee machine bolted to the wall. For one coin it dispenses something brown and very hot, and calls it café."],
  alan_coffee_ch1: ['alan', "Rui's coffee? I've seen what it does to Rui."],
  rui_hello: ['rui', "Alan. You look like you slept in a bookshop."],
  alan_rui_hello: ['alan', "You look like a man who hasn't slept, Inspector. We should swap. I've got plenty."],
  alan_ask_murders: ['alan', "Tell me about the drownings."],
  rui_murders_1: ['rui', "Three victims in nine days. Locked rooms, dry floors, not a drop of water anywhere. And every one of them has the Atlantic in their lungs. Cold, salt, with sand in it."],
  rui_murders_2: ['rui', "And on every pillow, a piece of tile. Same pattern. It's on the desk; look, don't touch. Somebody's signing their work."],
  alan_rui_locked: ['alan', "Locked rooms, dry beds, wet lungs. Even my love life makes more sense."],
  alan_ask_victims: ['alan', "Who were the victims?"],
  rui_victims_1: ['rui', "Ferreira, a clockmaker in the Baixa. Bastos, a retired teacher up in Graça, died in his siesta. Maria Coutinho, a fishwife in Madragoa."],
  rui_victims_2: ['rui', "All in bed. Each one within the same hour as the tide report. Which means nothing."],
  alan_ask_list: ['alan', "Did you find anything else?"],
  rui_list_1: ['rui', "A list, in Maria Coutinho's apron. Four old names. Ferreira. Bastos. Coutinho. And Sanches, old spelling. Any relation?"],
  alan_list_hand: ['alan', "[quietly] That's my grandfather's writing. [pause] He's been dead ten days. He wrote this before any of them died."],
  rui_water: ['rui', "Then do me a favour. Stay away from water, Sanchez."],
  alan_water: ['alan', "Inspector, I've been avoiding water for thirty-seven years. Ask my bathtub."],
  alan_ask_strange: ['alan', "Ever seen anything like this before?"],
  rui_drawer_1: ['rui', "In this building? There's a drawer upstairs that won't close. The only one. That's as strange as it gets."],
  rui_drawer_2: ['rui', "Not today, Alan."],
  alan_ask_fog: ['alan', "And this fog?"],
  rui_fog: ['rui', "The meteorologists say it's a temperature inversion. My mother says the river is breathing. I'm starting to prefer my mother."],
  rui_bye: ['rui', "Go home, Alan. Lock the door."],

  // ---------- Taberna da Saudade ----------
  narr_look_tavern: ['narr', "Lamplight, cigarette smoke, and the ghost of a thousand grilled sardines."],
  narr_look_photo: ['narr', "A yellowed photograph from nineteen thirty-four: a young Amália, dazzling, beside a serious young man in a bell-founder's apron. On the shelf behind them sits a music box inlaid with mother-of-pearl, a silver ship on painted waves."],
  alan_photo: ['alan', "That's... Grandfather. Young. And he's not looking at the camera. He's looking at her."],
  narr_look_bottles: ['narr', "Bottles of ginjinha, Lisbon's sour-cherry liqueur. Sweet as a first kiss, strong as a last one."],
  alan_take_bottle: ['alan', "Lino would break my fingers. I'd better pay for it."],
  alan_ginjinhas: ['alan', "Two ginjinhas. One for courage, one for the courage to drink the first."],
  alan_have_ginja: ['alan', "Any more and I'll be singing fado myself. Nobody wants that."],
  narr_look_guitar: ['narr', "A guitarra portuguesa: twelve steel strings and a teardrop body. It sounds the way rain looks."],
  narr_look_candle: ['narr', "A box of matches with a sailing ship on the lid, left at the end of the bar."],
  amalia_matches: ['amalia', "Take them. I have given up smoking eleven times."],
  alan_matches: ['alan', "Eleven times? Practice makes perfect."],
  narr_look_amalia: ['narr', "Dona Amália, once the most beautiful voice in the Alfama. The beauty has gone grey, but the voice has only gone deeper."],
  amalia_hello: ['amalia', "Joaquim's grandson. You have his face and none of his manners. Sit."],
  alan_ask_amalia_who: ['alan', "You knew my grandfather?"],
  amalia_who: ['amalia', "Knew him? I sang for him every night for two years. Then he married a sensible woman. Men are fools, menino. Bell-founders, twice over."],
  alan_ask_amalia_fog: ['alan', "What do you make of this fog?"],
  amalia_fog: ['amalia', "Fog is the city holding its breath, menino. Somebody always pays when it lets go."],
  alan_ask_amalia_photo: ['alan', "That photograph of you and Grandfather..."],
  amalia_photo: ['amalia', "Nineteen thirty-four. I was twenty, and he was a fool with good hands. That box behind us played our song."],
  alan_ask_amalia_song: ['alan', "Inês says you know a fado. 'O Sino Afogado.'"],
  amalia_song_no: ['amalia', "[dry] Not sober, menino. And never alone."],
  alan_give_ginja: ['alan', "Then let's not drink alone."],
  amalia_toast: ['amalia', "[softly] To Joaquim. Saúde."],
  alan_toast: ['alan', "To Grandfather. Who apparently had a life."],
  amalia_sing_1: ['amalia', "[singing] Nine days the fog lay on the river, nine nights the bronze lay in the deep. The founders cut its tongue for silence, and bound it with the blood they keep."],
  amalia_sing_2: ['amalia', "[singing] Where the old church prays without a roof, the stone weeps salt for what we did. Turn the letters seven times, son of the founders, and ring it back."],
  amalia_sing_3: ['amalia', "[singing] And if you fear, as founders feared, love, the sea will wait; the sea is long. Come back, come back, my bell-boy, and ring it backward with this song."],
  amalia_menino: ['amalia', "He sang it better. He wrote it, after all."],
  amalia_after_song: ['amalia', "Your grandfather made me promise never to sing that for a stranger. You're not a stranger. You're the last Sineiro, Alan. The last of the bell-hands."],
  alan_ringer: ['alan', "A ringer. I've been called many things, Dona Amália, but never a ringer."],
  amalia_called: ['amalia', "[laughs] Nobody calls you anything, menino. That's your trouble."],
  amalia_1955: ['amalia', "The last time the fog stayed this long, your grandfather came home with white in his hair. Ask the police about nineteen fifty-five."],
  alan_take_glass: ['alan', "For luck. And because I haven't stolen anything yet today."],
  amalia_sung: ['amalia', "Seven times, menino. Don't make an old woman sing twice."],
  amalia_bye: ['amalia', "Go with God. Or at least go with an umbrella."],
  narr_ch1_end: ['narr', "Alan had a ledger he couldn't read, a song he couldn't forget, and a grandfather who had known everything. It was a quarter past one. The river was due to turn at twenty-five past six, but nobody had told him that yet."],

  // ================================================================ CHAPTER II: THE UNEXPLAINED DRAWER
  narr_ch2_card: ['narr', "There is a drawer in every city that will not close. In Lisbon it was on the second floor of the Judiciária, and it had been open for forty years."],
  alan_ask_1955: ['alan', "What happened in nineteen fifty-five?"],
  rui_1955: ['rui', "Fifty-five? Before my time. [pause] But if it's in this building, it's in that drawer."],
  rui_drawer_crowbars: ['rui', "Bottom one. It's stood an inch open since before I joined the force. Crowbars, carpenters, once a priest. Nothing."],
  alan_look_drawer: ['alan', "Forty years and it still won't close. I own trousers like that."],
  alan_salted: ['alan', "A white crust along the seam. Sea salt. [pause] It isn't swollen. It's salted shut."],
  alan_drawer_pull: ['alan', "It won't budge. The salt's holding it like a grudge."],
  alan_coin_machine: ['alan', "My last coin, on the inspector's coffee. Most generous thing I've done since nineteen eighty-seven."],
  rui_coffee: ['rui', "That was my coffee."],
  alan_coffee: ['alan', "It died for a good cause."],
  narr_drawer_open: ['narr', "The salt hisses and runs like sugar in rain. With a groan that has waited forty years, the drawer slides open."],
  alan_read_file: ['alan', "Case fifty-five, one-fourteen. 'J. Sanches, bookseller, forty-three. Found the second body.' [pause] He never even told me when he found his glasses."],
  alan_lacerda_name: ['alan', "A. Lacerda, antiquarian, found in the cistern under the Carmo. There's an antiques shop in the Chiado with that name. Lisbon is full of Lacerdas. I'm not accusing a man of murder over a surname."],
  rui_times: ['rui', "The coroner was very precise. Ferreira, twelve minutes past three in the morning. Bastos, fifteen thirty-eight, in his siesta. Maria Coutinho, one minute past four."],
  rui_avo: ['rui', "My mother found a body in fifty-five. She never told me where. She still washes at the lavadouro. [pause] Don't tell her I sent you."],
  rui_key: ['rui', "And take this. Ferreira's shop is sealed. Forensics found nothing but clocks. If you find something, you found it by accident."],
  alan_accident: ['alan', "I'm very accident-prone. Ask anyone who's watched me cook."],

  // ---------- Lavadouro ----------
  alan_enter_lavadouro: ['alan', "Finally, somewhere in Lisbon wetter than the fog."],
  narr_look_basins: ['narr', "Stone basins as old as the Alfama, brimming with grey water and steam. Generations of gossip have been scrubbed out in them, and none of it has come clean."],
  narr_look_sheets: ['narr', "Wet sheets hang in rows like the sails of a fleet that never left harbour."],
  narr_look_arches: ['narr', "Gothic arches: ribs without flesh, reaching for a sky they lost two centuries ago."],
  narr_look_lav_arches: ['narr', "Fog leaks in through the arches and mixes with the steam, until it is hard to say where the river ends and the laundry begins."],
  narr_look_celeste: ['narr', "Dona Celeste Mendonça: seventy years old, built like a church door, forearms red from fifty years of other people's sheets."],
  celeste_twist: ['celeste', "If you want to talk, menino, talk while you twist. Take that end."],
  alan_wring: ['alan', "The last thing I twisted was the truth, and it came out cleaner than this."],
  celeste_hello: ['celeste', "Joaquim's boy. I'd know that chin in a fog. And look, we have one."],
  alan_ask_river: ['alan', "Rui says you think the river is breathing."],
  celeste_river: ['celeste', "It breathes four times a day, in and out. You don't sleep at a turning in a fog. Everybody's grandmother knows that. Nobody's grandson listens."],
  alan_breathes: ['alan', "The river breathes four times a day? I barely manage twice before lunch."],
  celeste_salt: ['celeste', "And salt is only the sea that forgot to leave. A little fresh water reminds it."],
  alan_show_tile: ['alan', "What do you make of this tile?"],
  celeste_tile_1: ['celeste', "That's not a tile. That's a mouthful of the sea, kept in clay. Nothing breaks it but what the bell remembers."],
  alan_dingdong: ['alan', "And what does a bell remember? Its first ding-dong, presumably."],
  celeste_cheeky: ['celeste', "[laughs] Cheeky. Bronze, menino. What else does a bell remember?"],
  alan_show_file: ['alan', "A washerwoman refused to sign a police report in fifty-five."],
  celeste_1955_1: ['celeste', "[pause] I was thirty. I didn't sign because I didn't want my name in a drawer with that thing."],
  celeste_1955_2: ['celeste', "At dawn on the tenth day I saw Joaquim Sanches and a small boy come up out of the Carmo grate, carrying something heavy in sailcloth. He looked like a man who had left the oven on."],
  alan_ask_maria: ['alan', "Did you know Maria Coutinho?"],
  celeste_maria: ['celeste', "She was my friend. I washed her boy's sweaters since he was born. Zé, on the river. Nobody told him to stay away from water either."],
  alan_ask_rui: ['alan', "Rui sends his... well. He didn't send me. Officially."],
  celeste_rui: ['celeste', "Is he eating?"],
  alan_rui_eating: ['alan', "Mostly coffee. Less than he used to."],
  celeste_bye: ['celeste', "Go on. And tell my son to eat something with a bone in it."],

  // ---------- Relojoaria Ferreira ----------
  alan_ferreira_sealed: ['alan', "Sealed with police tape. Rui gave me the key, which makes this a perfectly legal accident."],
  alan_ferreira_nokey: ['alan', "Sealed. Police tape and a padlock. I'd need a key, or a much worse character."],
  narr_ferreira_dark: ['narr', "Inside it is black, and very quiet. A clockmaker's shop should not be quiet."],
  alan_dark: ['alan', "I can't see a thing. Which, for a man who sells books, is a career-ending condition."],
  narr_look_oillamp: ['narr', "The shape of an oil lamp on the workbench, catching the grey light from the door."],
  alan_lamp_lit: ['alan', "Let there be light. Or a modest glow, like my career."],
  alan_enter_ferreira: ['alan', "Every clock stopped at the same minute. The only man in Lisbon who died on time."],
  alan_clocks: ['alan', "They didn't run down. They stopped. Together. Twelve minutes past three."],
  narr_look_clockwall: ['narr', "Forty clocks on one wall, every hand pointing at twelve minutes past three. The silence has a shape."],
  narr_look_workbench: ['narr', "Ferreira's bench: tweezers, loupes, a tin of tiny screws, and a cup of coffee that has grown a moustache."],
  narr_look_repairbook: ['narr', "Ferreira's repair book, written in a small, upright hand."],
  alan_repair: ['alan', "His last entries. A tide clock, 'for myself, because the river is keeping time and I want to see it.' And an old note: 'All my founder locks share one key-square. Old habit. Old families.'"],
  alan_repair_hint: ['alan', "Ferreira made Grandfather's desk lock. One key-square for all four families. So the desk key should fit anything he made for us."],
  narr_look_tideclock: ['narr', "A brass tide clock on the bench, beautifully made and quite dead. Its winding key is missing."],
  alan_clock_wound: ['alan', "It's turning. First thing in this city that's turned on for me in years."],
  narr_tideclock_runs: ['narr', "The clock ticks. Its second dial swings, slow as a breath, and settles on a word engraved in the brass: turning."],
  alan_need_times: ['alan', "A clock that tells the tide. Useful, if I knew what time things happened."],
  alan_turnings: ['alan', "Three twelve. Fifteen thirty-eight. Four oh one. [pause] They don't die at night. They die when the river turns."],
  alan_turnings_celeste: ['alan', "Celeste was right. Celeste is always right, apparently."],
  alan_tide_card: ['alan', "A tide table from a clockmaker. The only man in Lisbon who knew exactly when to come in."],
  alan_tide_today: ['alan', "Today's turnings. Twenty-five past six this evening. And twenty-five to one tonight."],
  narr_look_keyboard: ['narr', "A key board by the door, every hook labelled in Ferreira's careful hand. One tag reads 'Antig. L., vitrine, duplicate'."],
  alan_spare: ['alan', "Ferreira kept spares of everyone's locks. A clockmaker's revenge."],
  narr_look_shutters: ['narr', "The shutters are down. Outside, the Baixa goes about its business without one of its clockmakers."],
  narr_look_tape: ['narr', "Police tape across the door, and the grey street beyond it."],

  // ---------- Back at the shop ----------
  ines_pull: ['ines', "So. The deaths follow the tide, your grandfather was in that cistern in fifty-five, and a church that prays without a roof can only be the Carmo."],
  ines_tenth: ['ines', "And Alan... the seventeen fifty-five fog also lasted nine days. Then came the tenth morning. I've written forty pages about that morning."],
  alan_tenth: ['alan', "Write a forty-first. Make it boring."],
  narr_ch2_end: ['narr', "He knew when they died. He knew his grandfather had been there before. What he did not know was what Joaquim had carried up out of the dark, or why he had never put it down."],

  // ================================================================ CHAPTER III: THE WEEPING STONE
  narr_ch3_card: ['narr', "The Carmo had lost its roof in seventeen fifty-five and never asked for it back. Some buildings, like some men, prefer to see the sky they are afraid of."],
  alan_enter_carmo: ['alan', "No roof. Father Tomás must love an open plan."],
  narr_look_convent: ['narr', "The Convento do Carmo. The earthquake of seventeen fifty-five tore off its roof, and Lisbon never put it back. Now the fog fills the nave where the faithful used to."],
  narr_look_stone: ['narr', "A carved stone set into the wall, crusted thick with white salt, as if it has been weeping for a very long time."],
  alan_scrape: ['alan', "Like scraping a glacier with a library card."],
  narr_look_stoup: ['narr', "A stone stoup of holy water by the old north door. Somebody still fills it every morning."],
  alan_stoup_hand: ['alan', "I could cross myself, but I'd need something to carry it in. Holy water doesn't travel well in a fist."],
  alan_holy_glass: ['alan', "Holy water in a ginjinha glass. Sunday morning and Saturday night in one."],
  tomas_once: ['tomas', "Blessed water on a cursed stone. [pause] Once."],
  narr_stone_washed: ['narr', "The salt runs off in grey tears. Beneath it, a ring of carved letters circles a bell. The outer ring has been worn smooth by hands."],
  alan_stone_mag: ['alan', "Two alphabets, one inside the other, and the outer one turns. It's a cipher wheel. Carved in stone, by people with a lot of time and a very big secret."],
  alan_stone_nomag: ['alan', "There's carving under there, but it's too fine for the naked eye. And my eye is very naked."],
  alan_stone_crusted: ['alan', "Whatever's carved there is buried under a glacier of salt."],
  alan_cipher_wrong: ['alan', "That isn't Portuguese. That isn't even Polish."],
  narr_look_grate: ['narr', "An iron grate over a stair that leads down into darkness. The air rising from it smells of the sea."],
  alan_grate: ['alan', "Locked. And I don't like the way it's breathing."],
  narr_look_tomas: ['narr', "Father Tomás, keeper of a church with no roof. He sweeps the same flagstones every day, though the fog leaves no dust."],
  narr_look_chapel: ['narr', "A side chapel where the roof survived. Candles burn in red glass in front of a saint nobody remembers the name of."],
  tomas_hello: ['tomas', "The ruins close at dusk, my son. And the dead prefer their privacy."],
  alan_ask_carmo: ['alan', "How do you keep a church with no roof?"],
  tomas_carmo: ['tomas', "God took the roof and left the prayers. I keep the prayers."],
  alan_ask_founders: ['alan', "My family were bell-founders, apparently."],
  tomas_founders: ['tomas', "They cast the bells of this city for three hundred years. Fools twice over, your family. They made the bell, and then they rang it."],
  alan_twice: ['alan', "Twice? We were always overachievers."],
  alan_ask_stone: ['alan', "What's the stone in the wall?"],
  tomas_stone: ['tomas', "The weeping stone. Under the salt, it says what it says. It weeps every fog."],
  alan_ninth: ['alan', "Father... today is the ninth day."],
  tomas_iknow: ['tomas', "[softly] Yes. I know."],
  alan_ask_tomas_1955: ['alan', "My grandfather was here in nineteen fifty-five. With a boy."],
  tomas_notyet: ['tomas', "[a long pause] Not here. Not in daylight. Ask me at midnight."],
  tomas_bye: ['tomas', "Go in peace. While there is peace."],
  tomas_grate: ['tomas', "The grate stays locked, my son. Some doors are only for the dead and the foolish."],

  // decoding (cutscene)
  narr_decode_1: ['narr', "The letters turned, seven times, and the ledger began to speak in Joaquim's hand."],
  alan_decode_1: ['alan', "'The Brotherhood rang the drowned bell.' Well. That's the headline."],
  narr_1755: ['narr', "On All Saints' morning, seventeen fifty-five, a Sanches hand rang a bell beneath the Carmo, believing it a blessing. The earth answered first. Then the fire. Then the sea."],
  alan_rite_1: ['alan', "'Should the tongue be found, let the last of the bell-hand ring it backward...'"],
  narr_rite_2: ['narr', "'...against the order the founders rang the city: last to first, at a turning of the tide, with his own blood on the bronze.'"],
  alan_page3_read: ['alan', "'Nineteen fifty-five. Afonso Lacerda drowned in his own water. I had the tongue in my hand and the bell before me, and I ran.'"],
  narr_page3: ['narr', "'His boy watched. The Lacerdas are patient. God forgive me, so am I.'"],
  alan_page3: ['alan', "[quietly] He ran. He always said I got my legs from him. [pause]"],
  alan_surname: ['alan', "His boy. He'd be about fifty now. Lisbon is full of Lacerdas. Only one of them sells antiques."],
  tomas_order: ['tomas', "Last to first. The founders cast their bells in an order. Abílio at the Sé knows it better than God does."],
  alan_look_ledger_decoded: ['alan', "'Ring it backward, last to first.' Grandfather, you could have just left me a letter."],

  // ---------- The Sé bell tower ----------
  alan_climb: ['alan', "[out of breath] If God wanted me in a bell tower, He'd have put in a lift."],
  narr_look_setower: ['narr', "The bell chamber of the Sé. Four great bells hang in the dusty light from the louvres, each one older than the country's patience."],
  narr_look_abilio: ['narr', "Senhor Abílio, last hand-ringer of the Sé: eighty-one, stooped, with hands like shovels and a hearing aid that whistles when he's happy."],
  abilio_hello: ['abilio', "[shouting] VISITORS! NOBODY CLIMBS UP HERE BUT PIGEONS AND THE TAX MAN!"],
  alan_abilio_founders: ['alan', "I'm looking for the founders' order!"],
  abilio_borders: ['abilio', "[shouting] BORDERS? SPAIN'S THAT WAY."],
  alan_abilio_joaquim: ['alan', "Did you know Joaquim Sanches?"],
  abilio_joints: ['abilio', "[shouting] JOINTS? NO, THE JOINTS ARE FINE, THANK YOU. IT'S THE EARS."],
  alan_abilio_bells: ['alan', "Can you tell me about the bells?"],
  abilio_smells: ['abilio', "[shouting] SMELLS? IT'S THE PIGEONS. YOU GET USED TO IT. I DIDN'T."],
  alan_write_abilio: ['alan', "Finally, a man who reads what I mean instead of hearing what I say."],
  alan_w_joaquim: ['alan', "[writing] 'Joaquim Sanches. My grandfather.'"],
  abilio_joaquim: ['abilio', "[shouting] THE SANCHES BOY! HE RANG THE TENOR WITH ME IN TWENTY-SIX. WE WERE BOYS. HE HAD HANDS FOR IT. THEN HE WENT TO SELL BOOKS, THE IDIOT."],
  alan_w_1955: ['alan', "[writing] 'November, nineteen fifty-five.'"],
  abilio_1955: ['abilio', "[shouting, then quieter] THAT NOVEMBER WE DIDN'T RING. JOAQUIM ASKED ME NOT TO. ONLY TIME IN MY LIFE I OBEYED ANYBODY."],
  alan_w_backward: ['alan', "[writing] 'What does a bell rung backward sound like?'"],
  abilio_backward: ['abilio', "[suddenly quiet] A bell rung backward sounds like a breath drawn in. You'll know it when you hear it. Pray you don't."],
  alan_w_order: ['alan', "[writing] 'The order the founders cast their bells?'"],
  abilio_eyes: ['abilio', "[shouting] READ THEM YOURSELF, BOY. MY EYES ARE WORSE THAN MY EARS. EVERY BELL HAS ITS FOUNDRY MARK."],
  abilio_bye: ['abilio', "[shouting] MIND THE STAIRS! THEY'VE KILLED TWO BISHOPS!"],
  narr_look_bell_tower: ['narr', "A great bronze bell, green at the lip, with a foundry mark cast into its shoulder."],
  alan_bell_ferreira: ['alan', "Ferreira, sixteen eleven. Older than my overdraft. Only just."],
  alan_bell_bastos: ['alan', "Bastos, sixteen forty-eight. Thirty-seven years after Ferreira. I know how that feels."],
  alan_bell_coutinho: ['alan', "Coutinho, seventeen oh two. A new century, and still in the bell business."],
  alan_bell_sanches: ['alan', "Sanches, seventeen thirty-nine. The family's last hit."],
  alan_order: ['alan', "Last to first. Sanches, Coutinho, Bastos, Ferreira. [pause] Me first. Of course me first."],
  narr_look_ropes: ['narr', "Bell ropes, worn smooth and dark by sixty years of Abílio."],
  narr_look_louvres: ['narr', "Through the louvres, the city is a grey sea with a few red roofs sticking out of it, like the masts of ships that didn't make it."],
  alan_rope: ['alan', "Ring the Sé bells without permission? Abílio would have my ears. He could use them."],

  // ---------- Antiguidades Lacerda ----------
  narr_look_antiques: ['narr', "Antiguidades Lacerda. A hundred clocks tick in no particular agreement, as if each one keeps the time of a different century."],
  narr_look_clocks: ['narr', "Clocks, dozens of them. Not one agrees on the hour, which is perhaps the most honest thing in the shop."],
  narr_look_lacerda: ['narr', "Vicente Lacerda: silver hair, cream linen, and the patient smile of a man who has never once been told no."],
  lacerda_hello: ['lacerda', "Senhor Sanchez. The bookseller. Selling, I hope? You always look like a man who needs to sell."],
  alan_lac_clocks: ['alan', "That's quite a collection of clocks."],
  lacerda_clocks: ['lacerda', "I collect time. Other people's."],
  alan_collect: ['alan', "So do I. Mostly as library fines."],
  lacerda_charming: ['lacerda', "[amused] Charming."],
  narr_look_tagged: ['narr', "Four clocks on the shelf by the counter, each with a little brass tag."],
  alan_jc: ['alan', "'F, three twelve.' 'B, fifteen thirty-eight.' 'C, four oh one.' And 'J.C., eighteen twenty-five.' [pause] Three of these have stopped. The fourth is waiting. J.C. Not Joaquim; he was a Sanches."],
  alan_lac_case: ['alan', "What's in the glass case?"],
  lacerda_case: ['lacerda', "A bell's tongue. Eighteenth century. Not for sale. Some things are only for keeping."],
  lacerda_velvet: ['lacerda', "I would notice a single hair moved on that velvet, Senhor Sanchez."],
  alan_look_case: ['alan', "A tongue behind glass, untouchable. I've been on dates like that."],
  narr_look_case: ['narr', "A glass case. On red velvet lies a heavy bronze bell clapper, green with age and crusted with salt. A card reads: 'Not for sale.'"],
  alan_lac_joaquim: ['alan', "Did you know my grandfather? Joaquim Sanches."],
  lacerda_joaquim_day: ['lacerda', "I knew of him. A careful man. Careful men usually live a long time."],
  alan_lac_fog: ['alan', "Terrible weather."],
  lacerda_fog: ['lacerda', "I find it restful. Patient weather."],
  narr_look_musicbox: ['narr', "A music box inlaid with mother-of-pearl. A tiny silver ship sails forever on painted waves."],
  alan_box_photo: ['alan', "I've seen this. On a shelf behind my grandfather, in nineteen thirty-four."],
  lacerda_trinket: ['lacerda', "[a little too quickly] A trinket."],
  alan_lac_box: ['alan', "That music box with the silver ship. Does it play?"],
  lacerda_box: ['lacerda', "Its key is in the back. One moment. [pause] Touch nothing."],
  lacerda_hands: ['lacerda', "Ah. Please. Admire with the eyes, Senhor Sanchez. Hands are so... impulsive."],
  alan_case_locked: ['alan', "Locked. And he's the kind of man who'd know if I breathed on it."],
  alan_case_open: ['alan', "Ferreira's spare. [click] Clockmakers never forget a lock."],
  alan_swap: ['alan', "Two kilos of brass for one bronze tongue. Fair trade. Ish."],
  alan_noswap: ['alan', "He'd notice the dent in the velvet. I need something that weighs what it weighs."],
  lacerda_putback: ['lacerda', "[cold] Put it back. Patience is not infinite."],
  lacerda_back_box: ['lacerda', "The key. Listen."],
  lacerda_pale: ['lacerda', "You look pale, Senhor Sanchez. Another day, perhaps."],
  lacerda_another: ['lacerda', "A pretty tune. Another time, Senhor Sanchez."],
  alan_slip: ['alan', "[whispering] I've just slipped an antiques dealer the tongue, and he didn't feel a thing."],
  lacerda_bye: ['lacerda', "Until we meet again. And we will."],
  narr_ch3_lacerda: ['narr', "At a quarter past five, in a shop in the Chiado, a man looked at a brass weight sitting on velvet and smiled. He could wait. He had always been able to wait."],

  // ---------- Taberna (optional) ----------
  alan_ask_amalia_box: ['alan', "There's a music box in Lacerda's shop. Mother-of-pearl, a silver ship."],
  amalia_box_mine: ['amalia', "[pause] That box was mine. I gave it to Joaquim the day he married. It played our song."],
  alan_proof: ['alan', "Then the man who has it was in Grandfather's flat after he died. [pause] Or before."],

  // ---------- Back at the shop ----------
  ines_vandal: ['ines', "You stole a church bell's tongue from a murderer. Before tea."],
  alan_vandal: ['alan', "Cistern bell. Don't make me sound like a vandal. I'm a thief; there's a difference."],
  ines_salt_pages: ['ines', "Give me the ledger. The back pages are stuck together with salt. Look."],
  ines_steam: ['ines', "Archivist's trick. I'll steam them apart. Go and wash your face; you look like a man who's seen a clock."],

  // ================================================================ CHAPTER IV: THE FOUNDERS' BLOOD
  narr_ch4_card: ['narr', "Every family keeps a page it doesn't read. The Sanches family had kept theirs for two hundred years, stuck shut with salt."],
  ines_genealogy: ['ines', "They came apart. Alan, it's the founders. Four family lines from seventeen fifty-five. Most of them end in the eighteen hundreds. A few your grandfather kept alive, in his own hand."],
  alan_genealogy: ['alan', "My whole family on one page. Shorter than I hoped, longer than they deserved."],
  alan_read_coutinho: ['alan', "The last thing he wrote. 'Maria Coutinho, fishwife, Madragoa. Her son José, no father registered, fisherman, the Maria Fé, Cais do Sodré. I have told Maria. I have not told the boy.'"],
  alan_jc_click: ['alan', "J.C. [pause] José Coutinho. Lacerda has a clock for him, and it says twenty-five past six."],
  ines_time: ['ines', "It's twenty past five, Alan."],
  alan_celeste_sweaters: ['alan', "Maria's boy. Celeste washes his sweaters. Zé."],
  alan_jc_unknown: ['alan', "José Coutinho. Maria's son, on a boat at Cais do Sodré, and he doesn't even know. The next turning is twenty-five past six."],
  ines_kettle: ['ines', "Go. I'll keep ringing Rui, and I'll keep the kettle on."],
  alan_ledger_with_ines: ['alan', "Keep reading. If anybody asks, you never saw this book, and I've never read one."],

  // ---------- Cais do Sodré ----------
  alan_enter_cais: ['alan', "Cais do Sodré. Where Lisbon comes to make bad decisions after midnight. It's barely six."],
  narr_look_cais: ['narr', "The quay is a smear of grey: fishing boats moored three deep, gulls arguing on the bollards, and the river breathing somewhere under the fog."],
  narr_look_harbourclock: ['narr', "The harbour clock on its iron post. It has kept time for the fishermen for a hundred years, and it is not about to stop for fog."],
  narr_look_boats: ['narr', "Three fishing boats moored abreast. The outermost has a name freshly painted on her bow: Maria Fé."],
  narr_look_crates: ['narr', "Crates of ice and silver fish, and the smell of the sea in its working clothes."],
  narr_look_phonebox: ['narr', "A red telephone box, misted on the inside, as if someone had been crying in it. Or making a very long call."],
  alan_phone_cais_early: ['alan', "No time for calls. For once in my life I have an excuse."],
  celeste_quay_hello: ['celeste', "Menino! Twice in one day. People will talk."],
  alan_ask_ze: ['alan', "I'm looking for Zé Coutinho. It's urgent."],
  celeste_ze: ['celeste', "Zé? I'm his madrinha. He fishes nights and sleeps days, and he bolts the hatch. Nobody wakes Zé before dark. Not even me. Not since his mother."],
  alan_ask_boat: ['alan', "Which boat is his?"],
  celeste_boat: ['celeste', "The Maria Fé. Outboard, past the Esperança and the Rosa. Mind the gaps; the river likes a joke."],
  alan_ask_wake: ['alan', "How do I wake him? Knocking doesn't work."],
  celeste_wake: ['celeste', "Storms don't wake him. Shouting doesn't. Only the boat moving wrong. He feels it in his teeth."],
  celeste_quay_bye: ['celeste', "Go, menino! And mind your feet!"],
  alan_sea_legs: ['alan', "[wobbling] Whoa. Whoa. I have the sea legs of a library chair."],

  // ---------- The Maria Fé ----------
  narr_look_deck: ['narr', "Wet planks, coiled rope, and a stern that has seen more weather than most churches."],
  narr_look_hatch: ['narr', "A hatch to the cabin, bolted from the inside. A sound comes up through it like a cello with a cold. Snoring."],
  alan_knock: ['alan', "Zé! It's your life calling! [pause] He's screening."],
  alan_shout: ['alan', "[shouting] ZÉ! WAKE UP! [pause] Nothing. He sleeps like I do. Professionally."],
  narr_look_porthole: ['narr', "Fog on the glass. A shape in a narrow bunk. And on the blanket, something blue."],
  narr_look_porthole_empty: ['narr', "Fog on the glass. The bunk is empty now, the blanket thrown back."],
  narr_look_line: ['narr', "The mooring line, made fast to the next boat with a bowline swollen tight with wet."],
  alan_knot_fail: ['alan', "I know two knots, and they're both called 'tangled'."],
  celeste_knot: ['celeste', "[shouting from the quay] Pull the tail back through the loop, menino! You want it undone, not your opinion of it!"],
  alan_untied: ['alan', "Look at that. I untied something without a lawyer."],
  narr_look_shipbell: ['narr', "A small brass ship's bell by the wheelhouse, green with salt."],
  alan_ring_shipbell: ['alan', "Ring a bell at a man who sleeps through storms? I'm bad enough at bells already."],
  narr_look_ze: ['narr', "Zé Coutinho: thirty-four, unshaven, built like a mooring post, with a black band on his sleeve."],
  ze_ten: ['ze', "[furious] You've got ten seconds, and then you're in the river."],
  ze_who: ['ze', "Who the hell are you?"],
  alan_tide_sense: ['alan', "A bookseller with a terrible sense of timing and an excellent sense of tide."],
  alan_danger: ['alan', "You're in danger."],
  ze_fromyou: ['ze', "From you?"],
  alan_show_card: ['alan', "Look at this. It's a tide table. Find your mother's time."],
  ze_card: ['ze', "[pause] Four oh one. Right on the turn."],
  ze_turning: ['ze', "She always said don't sleep at the turn. I thought it was a fishwife thing."],
  alan_ask_ze_tile: ['alan', "Zé. Has anything strange turned up? Anything blue?"],
  ze_tile: ['ze', "There was a blue thing in my bunk when I came in this morning. I thought it was from her things."],
  ze_file: ['ze', "A docker, drowned in his bed, fifty-five. [pause] My grandfather was a docker. My mother never said how he died."],
  ze_list: ['ze', "That's my mother's name. In a dead man's writing. [pause] Keep talking."],
  ze_cabin: ['ze', "Down there. Hurry up, before I change my mind."],

  // ---------- The cabin ----------
  narr_look_cabin: ['narr', "A cabin the size of a confession box. A photograph of a woman is nailed above the bunk."],
  narr_look_maria: ['narr', "Maria Coutinho, laughing at whoever held the camera, a basket of sardines on her hip."],
  narr_look_bunktile: ['narr', "A blue tile on a soaked blanket. The puddle around it is spreading. Uphill."],
  alan_take_tile: ['alan', "Cold, wet and heavier than it should be. Like my last relationship."],
  alan_hammer: ['alan', "[strains] It bounced. Like hitting the sea."],
  narr_look_hammer: ['narr', "Zé's hammer, on a bench of tools that smell of tar and fish."],
  alan_ask_tongue: ['alan', "Bronze breaks what iron won't. So, Zé. How do you feel about tongues?"],
  ze_justdo: ['ze', "Just do it."],
  narr_turn: ['narr', "At twenty-five past six the river turned, and for the first time in nine days, nobody drowned."],
  alan_turned: ['alan', "[quietly] Twenty-five past six. [pause] Your mother would have wanted you awake for this."],
  ze_knew: ['ze', "She knew. All this time. She just told me to keep my boots on in a fog."],
  alan_two_sentences: ['alan', "Your family and mine made a bell in seventeen fifty-four, and somebody wants us both to pay for it. That's the two sentences. The joke is that I'm the one who came to save you."],
  ze_knife: ['ze', "If somebody's going to ring a bell for my mother, take this. You look like a man who'll have to cut something tonight."],
  alan_pessoa_mention: ['alan', "Thank you. I should get back. I've a cat who thinks I'm late with his dinner. He's right."],
  ze_sardine: ['ze', "[gruff] For the cat. Not for you."],
  alan_sardine: ['alan', "Pessoa will finally respect me."],
  ze_river: ['ze', "If you need the river, I'm on it."],
  // romance: Zé and Alan, after the curse breaks
  ze_rom_1: ['ze', "[low, rough] That thing took my mother. And a bookseller breaks it with a bell's tongue. Come here."],
  alan_rom_1: ['alan', "[nervous, talking fast] I should mention I bruise easily, and I talk when I'm nervous, and right now I am extremely—"],
  ze_rom_2: ['ze', "[quiet, commanding] Stop talking, Sanchez."],
  narr_rom_1: ['narr', "For thirty-seven years, Alan Sanchez had talked his way out of everything. Zé Coutinho did not leave him the room. For once in his life, Alan did not want it."],
  narr_rom_2: ['narr', "The bunk complained, and the boat rocked, and nobody was counting. It was over almost as fast as it began."],
  alan_rom_2: ['alan', "[sleepy, smiling] So. That happened."],
  ze_rom_3: ['ze', "[gruff, matter-of-fact] It did. Button your shirt, bookseller. You've still got a bell to ring."],
  alan_rom_3: ['alan', "[softly, happy] Yes, Captain."],
  alan_ringout: ['alan', "[pause] She always answers. She answers when it's for me and I'm standing right next to it."],
  narr_ch4_end: ['narr', "The note from the tongue crossed the river and climbed the Chiado and found the man it was meant for. He put down his coffee. He went to fetch his coat. In a bookshop in the Alfama, a kettle boiled dry."],

  // Celeste's hints on the quay (Ch. IV)
  celeste_hint_boat: ['celeste', "The Maria Fé, menino! The far one! Go!"],
  celeste_hint_wake: ['celeste', "I told you. Move the boat wrong and he'll come up like a cork."],
  celeste_hint_knot: ['celeste', "The line, menino! Tail back through the loop!"],
  celeste_hint_ze: ['celeste', "Show him something, not your face. Zé believes in paper and fish."],
  celeste_hint_tile: ['celeste', "Bronze, menino. You have bronze. What else does a bell remember?"],

  // ================================================================ CHAPTER V: THE DROWNED BELL
  narr_ch5_card: ['narr', "Night came early, as it does in fog, and found the door of the Livraria Sanchez standing open, which it had not done in a hundred years."],
  alan_ines_gone: ['alan', "[quietly] Inês? [pause]"],
  narr_look_salt_line: ['narr', "A line of salt runs across the floorboards from the door to the counter, like the mark a tide leaves when it goes out."],
  narr_look_kettle_dry: ['narr', "The kettle lies on its side on the cold ring. It has boiled dry, and the room smells of hot metal and fog."],
  alan_look_pessoa_machine: ['alan', "He's asleep on the answering machine. It's warm, and it's the one thing in the room I need. Naturally."],
  alan_take_pessoa_machine: ['alan', "He's dug in. Nine kilos of no, now with added loyalty."],
  alan_lamp_machine: ['alan', "He's learned. The machine is warm by itself. One of us has learned something today."],
  alan_hint_bribe: ['alan', "Bribes. He responds to bribes. Like a Lisbon official."],
  alan_pessoa: ['alan', "[pause] He was lying on the ledger. She hid it under the cat before he came. Nine kilos of loyalty. Who knew."],
  lacerda_msg3: ['lacerda', "[cold, measured] Senhor Sanchez. Your assistant has been reciting dates to me. She mentions a book. Bring it. Bring the tongue, and your blood. Come alone, under the Carmo. The river turns at twenty-five to one."],
  alan_queue: ['alan', "He wants my blood. He'll have to queue behind my landlord."],
  alan_alone: ['alan', "Come alone. Finally, something I'm qualified for."],
  narr_msg2_again: ['narr', "The machine clicks, and plays the second message again. Eight seconds of dripping water."],
  alan_hangup_reveal: ['alan', "He rang this morning to see if I was home. He's been patient all day."],
  alan_call_rui: ['alan', "Rui. It's Alan. Lacerda has Inês. The Carmo, twenty-five to one."],
  rui_gate: ['rui', "[pause] Midnight at the Carmo. I'll be outside the gate. If I go in, it's a police matter, and then it's in a drawer forever."],
  alan_box_tell: ['alan', "And Rui, he has Amália's music box. The one she gave my grandfather. It was in his flat."],
  rui_murder: ['rui', "Then it's murder. Unexplained, but murder."],
  alan_obituary: ['alan', "If I'm not out by dawn, Rui, the obituary says 'witty'. Not 'lazy'. 'Witty'."],
  alan_door_ledger: ['alan', "Not without the ledger. Whatever Inês did with it, she did it on purpose."],

  // ---------- Taberna (optional, night) ----------
  narr_tavern_night: ['narr', "The chairs are up on the tables. One lantern burns. Amália is singing to an empty room, and she does not stop when he comes in."],
  amalia_night_sing: ['amalia', "[singing softly, alone] Come back, come back, my bell-boy, and ring it backward with this song."],
  amalia_alone: ['amalia', "Joaquim ran because he was alone down there. You are not alone, menino. Somebody is waiting for you, which is more than he ever had."],
  alan_amalia_thanks: ['alan', "That's the nicest thing anyone's said to me all week. Which tells you about my week."],

  // ---------- The Carmo at midnight ----------
  narr_look_convent_night: ['narr', "Moonlight in a roofless nave. The grate stands open, and a green light breathes up from below."],
  narr_look_tomas_night: ['narr', "Father Tomás, waiting with a lantern, as if he has been standing here since nineteen fifty-five."],
  tomas_night_hello: ['tomas', "I knew you would come. I have been waiting for you longer than you have been alive."],
  alan_ask_midnight: ['alan', "It's midnight, Father. You said to ask."],
  tomas_boy: ['tomas', "I was eleven. I held his lantern. The water came up to my knees, and he had the tongue in one hand and the bell in front of him."],
  tomas_ran: ['tomas', "He didn't run from the bell, Alan. He picked me up and ran. He was ashamed of it for forty years, and he was wrong to be."],
  tomas_count: ['tomas', "I have counted every fog since. I knew which day this was before you did."],
  alan_thanks: ['alan', "[pause] Thank you, Father."],
  tomas_lantern: ['tomas', "Take the lantern. Hold it higher than he did."],
  rui_nothing: ['rui', "[exhales smoke] I didn't see you go in."],
  alan_rui_gate: ['alan', "You never do, Rui. It's your best quality."],
  alan_descend: ['alan', "'Stay away from water,' he said. Midnight, a flooded church basement, a dead man's bell. Rui will be livid."],
  alan_need_lantern: ['alan', "Down there, in the dark? Not without a light. I've seen how that ends; I sell those books."],

  // ---------- The cistern ----------
  narr_look_cistern: ['narr', "A vast flooded cistern beneath the city. Black water, stone pillars, and above the water, on a rusted chain, a great bronze bell. Silent. Waiting."],
  narr_look_bell: ['narr', "The Drowned Bell, tongueless, hanging mute over the black water. Its bronze is carved with four great waves."],
  narr_look_marks: ['narr', "Six marks are painted up the pillar, one above the other. The lowest is already wet."],
  narr_look_walkway: ['narr', "A narrow stone walkway runs out over the water to the bell. It was built for founders, not for booksellers."],
  narr_look_lacerda_robe: ['narr', "Vicente Lacerda, in the robe of a brotherhood that should have died two hundred years ago. It suits him."],
  narr_look_ines_tied: ['narr', "Inês, tied to a pillar with wet rope. Furious, mostly. Frightened, a little. Alive."],
  lacerda_joaquim: ['lacerda', "A single drop of seawater, on the heart. He said your name. I thought that was touching."],
  alan_fin_angry: ['alan', "[angry, quiet] You killed him."],
  lacerda_spared: ['lacerda', "You were the only founder who never asked your grandfather a single question. I was grateful."],
  lacerda_ze: ['lacerda', "You broke my tile. Clumsy. No matter. Maria knew, so I assumed the son did. One cannot be too careful."],
  lacerda_demand: ['lacerda', "Joaquim's book first. Then cut your hand, wet the bronze, and ring, and she walks out of here. Patient, Senhor Sanchez. I have been patient for forty years."],
  ines_warn: ['ines', "[shouting] Alan, the water rises every time that bell rings! Don't ring it his way!"],
  lacerda_quiet: ['lacerda', "Quiet, my dear."],
  // running gag: everyone notices Alan only flirts with men; Alan, officially in the closet, changes the subject
  gag_ines_1: ['ines', "[dry] A woman? In four years I've never once seen you look at one."],
  gag_alan_ines_1: ['alan', "[flustered, too fast] I look at lots of women. My mother. The bank manager. Is that the machine? That's the machine."],
  gag_lino: ['lino', "[knowing] And one more after his set, for Duarte? On the house. He likes the cherries too."],
  gag_alan_lino: ['alan', "[flustered] For Dona Amália. A lady. I buy ladies drinks constantly. Keep the cherry."],
  gag_amalia: ['amalia', "[amused, softly] Joaquim looked at me the way you look at my guitarist, menino. At least he picked a singer."],
  gag_alan_amalia: ['alan', "[coughs] Professional interest. I stock books on... strings. Lovely ashtray. Is it new?"],
  gag_celeste: ['celeste', "And you, menino? Is there a nice girl feeding you?"],
  gag_alan_celeste: ['alan', "[flustered] There's the cat. I feed him. It's complicated. Tell me about the river."],
  gag_abilio_1: ['abilio', "[shouting] AND YOU, BOY? MARRIED? A NICE GIRL?"],
  gag_alan_abilio: ['alan', "[writing, hurried, under his breath] 'Bells. Let's talk about bells.'"],
  gag_abilio_2: ['abilio', "[shouting, delighted] HE BLUSHES! THE SANCHES BOY BLUSHES IN INK!"],
  gag_celeste_quay: ['celeste', "Half the girls in Madragoa have tried 'urgent' on Zé. Never a bookseller. Funny, that."],
  gag_alan_celeste_quay: ['alan', "[flustered] It's tidal. Purely tidal. Which boat did you say?"],
  gag_ze: ['ze', "[gruff, amused] Celeste will ask why you were down here so long."],
  gag_alan_ze: ['alan', "[flustered] Tide tables. Very dense. So many columns."],
  gag_tomas: ['tomas', "And when this is done, my son, go and find whoever you were thinking of on those steps. God is less particular than His Church."],
  gag_alan_tomas: ['alan', "[flustered] I was thinking about the cat. Mostly. Thank you, Father."],
  gag_rui: ['rui', "[exhales smoke] Teixeira asked me if you were single. I told him you sell books. Same thing."],
  gag_alan_rui: ['alan', "[flustered] Tell him... tell him nothing. Is that the time? It's the time."],
  gag_ines_2: ['ines', "[teasing] And on the way you can explain why you smell of tar and a fisherman's sweater."],
  gag_alan_ines_2: ['alan', "[flustered] It's a very fishy city. Come on. The sun, Inês. Look at the sun."],
  alan_look_sketch: ['alan', "A bell under three waves. Blue on white. I've drawn better. I've also drawn worse."],
  lino_talk_1: ['lino', "[wiping a glass, knowing] You keep looking at Duarte like he's the last pastel de nata in Lisbon, menino."],
  alan_lino_1: ['alan', "[flustered] I'm admiring the woodwork. On the guitar. Is that... cherry? Speaking of cherries. Ginjinha. Possibly."],
  lino_talk_3: ['lino', "[chuckles] Two coins, when you've decided which one you're thirsty for."],
  lino_talk_2: ['lino', "Ginjinha's two coins. Looking is free. Mostly."],
  // background characters you can talk to
  cards_talk_1: ['cards', "[gruff, not looking up] Sueca is a game for four, rapaz. We've been playing it two-handed since the Revolution. Don't sit down."],
  alan_cards_1: ['alan', "I wouldn't dream of it. I can't count past trumps."],
  cards_talk_2: ['cards', "[slaps a card down] Trunfo! ...You're still here?"],
  fish_talk_1: ['fish', "[loud] Sardines, menino! Caught this morning, fresher than you'll ever be!"],
  alan_fish_1: ['alan', "I'm only browsing."],
  fish_talk_2: ['fish', "[loud, scandalised] Browsing? It's a fish crate, not a bookshop!"],
  fish_talk_3: ['fish', "[loud] Two hundred escudos the dozen! Looking is free, smelling costs extra!"],
  mender1_talk_1: ['mender1', "[weathered, slow] Forty years I've mended nets on this quay. Never seen the river sulk like this. The gulls won't land, and the tide comes in wrong."],
  mender1_talk_2: ['mender1', "[weathered] Ask Celeste. She knows the river better than the river does."],
  mender2_talk_1: ['mender2', "[gruff] You're standing in my light, bookseller."],
  alan_mender2_1: ['alan', "Sorry. Occupational hazard."],
  mender2_talk_2: ['mender2', "[gruff] Still in my light."],
  nun_talk_1: ['nun', "[whispering] The stone has been weeping since Sunday. Mother Superior says it's damp. I say it's grief."],
  alan_nun_1: ['alan', "[whispering] Maybe it's both."],
  nun_talk_2: ['nun', "[whispering] Shh. Even the stones are listening today."],
  // hints and fixes from the script review
  narr_look_case_after: ['narr', "A glass case. On red velvet sits a two-kilo brass weight. The card still reads 'Not for sale.' For once, it's true."],
  alan_phone_ch5_early: ['alan', "And tell Rui what? 'Inês is out and the kettle's dry'? He'd send me a form."],
  ines_hint_celeste: ['ines', "Rui's mother is at the lavadouro. She won't talk to idle hands, so lend her yours."],
  ines_hint_look: ['ines', "A drawer that won't close for forty years isn't stuck, Alan. Look closer. You own a magnifying glass."],
  ines_hint_mag: ['ines', "Whatever's carved there is small. Use the magnifying glass, for once in your life."],
  ines_hint_desk2: ['ines', "The desk's free, Alan. You have the key. I'm not doing it for you."],
  ines_hint_box: ['ines', "Get him out of the room. Ask about something he loves more than you. That music box, say."],
  celeste_hint_phone: ['celeste', "[shouting] Menino! That telephone box has been ringing for you. Your girl from the bookshop, twice, and she sounded frightened. Ring her back!"],
  // finale rewrite: Lacerda lets Inês hold the lamp, and never suspects the order until the last note
  alan_ask_lamp: ['alan', "I can't strike what I can't see, and I need both hands. Let her hold the lantern."],
  lacerda_lamp_ok: ['lacerda', "[amused, not looking up] By all means. Cut her loose. The water answers to me, Senhor Sanchez. Where would she go?"],
  lacerda_ledger_first: ['lacerda', "[softly] The ledger first, Senhor Sanchez. I should like to read along."],
  alan_strike_1: ['alan', "[under his breath] Last to first, Grandfather."],
  lacerda_good_1: ['lacerda', "[pleased, turning a page] Good. I can feel it in the stone."],
  lacerda_good_2: ['lacerda', "[delighted] Yes... yes. The river is listening."],
  lacerda_good_3: ['lacerda', "[eager, rising] One more, Senhor Sanchez. One more, and it is mine."],
  lacerda_realise: ['lacerda', "[slowly, horrified] That was... backward. You rang it backward. All of it!"],
  lacerda_lovely: ['lacerda', "[purring] Lovely. Again."],
  ines_hint_ledger: ['ines', "He wants the founders, Alan. Let him have Joaquim's book."],
  ines_hint_free: ['ines', "Get me out of these ropes. Tell him you need the light."],
  lacerda_patient: ['lacerda', "[softly] Patient."],
  alan_glacier: ['alan', "Vicente, I've met glaciers with more urgency."],
  lacerda_death: ['lacerda', "Ah, ah. I said I am patient. I never said I was slow."],
  narr_death: ['narr', "The water rises to meet Alan Sanchez, last of the Sineiros. Lisbon will not see the sun again. Perhaps try something a little less... direct."],
  alan_offer: ['alan', "You want the founders? Here. Every line you missed. Two hundred years. In my grandfather's hand."],
  lacerda_cant: ['lacerda', "[hungry] Cipher. Of course. Joaquim, you careful old man."],
  alan_seven: ['alan', "The rite's in cipher. The founders' names aren't. Start at the back."],
  lacerda_ledger: ['lacerda', "[greedy whisper] At last... every line... every one I missed..."],
  alan_cut_watched: ['alan', "Not while he's watching. The water listens to him."],
  ines_free: ['ines', "[rubbing her wrists] You took your time."],
  alan_cat: ['alan', "I had a cat to bribe."],
  ines_lantern: ['ines', "I've got it. Go on, Alan. Ring."],
  narr_bell_lit: ['narr', "Inês lifts the lantern high. In the carved waves of the bronze, four foundry marks catch the light: four names, four families, four centuries of patience."],
  alan_too_dark: ['alan', "Too dark, and I need both hands."],
  ines_no: ['ines', "Alan..."],
  alan_papercut: ['alan', "[sharp breath] Paper cut. I've had worse from Camões."],
  alan_need_blood: ['alan', "'With his own blood on the bronze.' Grandfather's ledger was very specific, and I was hoping it was a metaphor."],
  alan_ringback: ['alan', "I never rang anyone back in my life, Grandfather. Let's start with you."],
  lacerda_no: ['lacerda', "[roaring] NO! Not backward! NOT BACKWARD!"],
  lacerda_strike_2: ['lacerda', "[shouting] The water is mine! Rise! RISE!"],
  lacerda_strike_3: ['lacerda', "[desperate] Stop him! Do you hear me? I command you!"],
  alan_wrong_strike: ['alan', "Wrong number."],
  narr_wrong_strike: ['narr', "The bell rings forward, one deep note, and far above, faintly, the bells of the city answer."],
  ines_hint_eyes: ['ines', "Get his eyes off you first."],
  ines_hint_ropes: ['ines', "Alan. The knife. Then the light."],
  ines_hint_light: ['ines', "I can hold the lantern. Give it to me."],
  ines_hint_blood: ['ines', "'His own blood on the bronze,' Alan. You read it to me."],
  ines_hint_lastfirst: ['ines', "Last to first, Alan. Who came last?"],
  narr_ring: ['narr', "The bell does not ring so much as un-ring: a sound pulled backward out of the air, out of the stone, out of the river itself."],
  narr_silence: ['narr', "The fog is drawn down the steps like a breath. And the water stops obeying."],
  lacerda_mine: ['lacerda', "[screaming] The water is mine. It answers to me!"],
  alan_answers: ['alan', "It answered. It's been waiting longer than you."],
  narr_end_1: ['narr', "The black water rises around Lacerda, and only Lacerda. To his knees. His chest. His mouth. He goes under with the ledger in his hands."],
  alan_ledger: ['alan', "Some books should go with their readers."],
  narr_still: ['narr', "The water goes still, and clear. The bell hangs silent, tongueless again. The tongue lies on the ledge, cold at last. Alan pockets it anyway. Old habit."],
  ines_end: ['ines', "[breathless] Alan... the fog. Can you feel it? It's lifting."],
  alan_end: ['alan', "Come on. Let's go and see what the city looks like."],
  alan_dawn: ['alan', "The tenth morning. The first one I've seen before eleven in years."],
  rui_coffee_back: ['rui', "I owed you one. Actually, you owed me one. I've stopped keeping track."],

  // ---------- Epilogue ----------
  narr_epilogue: ['narr', "On the tenth morning, the fog lifted from Lisbon. The sun rose over the river, the trams rang, and nobody drowned. Nobody noticed. Which, Alan decided, was exactly how it should be."],
  narr_epi_drawer: ['narr', "At the Judiciária, Rui Mendonça filed case ninety-five, two-oh-three as unexplained, laid it on top of fifty-five, one-fourteen, and pushed the drawer."],
  rui_click: ['rui', "[surprised] Huh."],
  narr_epi_shop: ['narr', "At the Livraria Sanchez, a bronze tongue sat on the bookbinding press, holding down the Camões nobody bought, where the brass weight used to be. Inês was writing page forty-one."],
  narr_vig_box: ['narr', "Rui returned a music box to Dona Amália, 'from the estate of an unknown person'. She wound it, and did not sing along."],
  narr_vig_night: ['narr', "That evening the Taberna was full, and for the first time in her life Amália sang 'O Sino Afogado' to a full room. Alan bought the ginjinhas."],
  narr_vig_ze: ['narr', "On the quay at Cais do Sodré, Celeste handed her godson a clean sweater and asked, very innocently, whether the bookseller would be needing his boat rocked again. Zé went the colour of a boiled prawn, and did not say no."],
  narr_vig_abilio: ['narr', "At noon, for no reason at all, Abílio rang the bells of the Sé, and the whole Alfama heard a city that was very much awake."],
  narr_call: ['narr', "Alan opened his notebook to the number he had been afraid to call. His mother answered on the second ring. He said, 'Mãe, it's me,' and then, for once, he didn't make a joke."],
  ze_back: ['ze', "[pause] Not mine to keep. [softly] Tell Alan he left it on my bunk. He can come and fetch it himself."],
  narr_post: ['narr', "In a shuttered shop in the Chiado, beside a clock that had stopped at twenty-five past six, a clock that nobody had wound began to tick."],

  // ================================================================ AMBIENT NPCS
  alan_npc_busy: ['alan', "They're busy. Somebody in this city has to be."],
  alan_npc_laundry: ['alan', "Drying laundry in nine days of fog. That's not optimism, that's faith."],
  alan_npc_bench: ['alan', "My future, ladies and gentlemen. Rehearsing."],
  alan_npc_tram: ['alan', "Tram 28. Never on time, always on rails. We have that half in common."],
  alan_npc_typing: ['alan', "He's on page four hundred of a report nobody will read. My kind of author."],
  alan_npc_phone: ['alan', "Either his mother or his lawyer. Same face for both."],
  alan_npc_lino: ['alan', "Lino. Pours like a priest, charges like a bishop."],
  alan_npc_cards: ['alan', "Sueca. They've been playing the same game since Salazar. One of them is winning."],
  alan_npc_guitar: ['alan', "He tunes for an hour and plays for three minutes. I respect the ratio."],
  alan_npc_couple: ['alan', "Either in love or planning a murder. In this city, why not both."],
  alan_npc_washers: ['alan', "They know everything in the Alfama by Thursday. They knew about me by Tuesday."],
  alan_npc_nun: ['alan', "Praying under no roof. Direct line, no switchboard."],
  alan_npc_pigeons: ['alan', "Lisbon's real congregation."],
  alan_npc_menders: ['alan', "Knots. These men are why I'll never be a sailor."],
  alan_npc_docker: ['alan', "He's carried more today than I have in my life. Including grudges."],
  alan_npc_fish: ['alan', "Sardines. If Pessoa saw this, he'd finally get up."],
  alan_npc_gulls: ['alan', "Flying rats with a sea view."],

  // ================================================================ ITEMS
  alan_look_notebook: ['alan', "Shopping lists, a sonnet I never finished, and a phone number I'm afraid to call. Ringing people back was never my strong suit."],
  alan_look_coins: ['alan', "Escudos. Enough for a coffee, or two glasses of something better."],
  alan_look_key: ['alan', "A small iron key, faintly sticky. Grandfather's idea of security was diabetes."],
  alan_look_ledger: ['alan', "Letters like a drunk's alphabet. And at the end, Grandfather's hand."],
  alan_look_ledger_genealogy: ['alan', "Every founder line since seventeen fifty-five. My family tree, and it's mostly stumps."],
  alan_look_magnifier: ['alan', "Brass and glass. Makes everything bigger, including my problems."],
  alan_look_weight: ['alan', "Two kilos of brass. Pointless, heavy and loyal. Inês says it reminds her of someone."],
  alan_look_ginja: ['alan', "Two small glasses of ginjinha, carefully not spilled. Yet."],
  alan_look_ginja_one: ['alan', "One ginjinha. Mine. For later. Or for courage. Whichever comes first."],
  alan_look_matches: ['alan', "Amália's matches. A sailing ship on the lid, and eleven failed resolutions inside."],
  alan_look_glass: ['alan', "An empty ginjinha glass. A souvenir of the only song anyone's ever sung at me."],
  alan_look_holywater: ['alan', "Holy water in a liqueur glass. If I spill it, I think that's a sin. If I drink it, it's definitely one."],
  alan_look_coffeecup: ['alan', "Rui's coffee. Hot enough to strip paint, and possibly salt."],
  alan_look_file: ['alan', "A photocopy of case fifty-five, one-fourteen. The original stays. The drawer would want it back."],
  alan_look_fkey: ['alan', "The key to a dead man's shop, from a policeman who didn't give it to me."],
  alan_look_tidecard: ['alan', "Ferreira's tide table. In the margin: 'The river keeps strange hours in fog.' So do I."],
  alan_look_vkey: ['alan', "A spare key to Lacerda's glass case. Somewhere, a clockmaker is smiling."],
  alan_look_tongue: ['alan', "The bell's tongue. Heavy, cold, and humming very faintly, as if it remembers something."],
  alan_look_tongue_wet: ['alan', "My blood on the bronze. Grandfather, I hope you're watching. And that you're not squeamish."],
  alan_look_knife: ['alan', "Zé's knife. A fisherman's blade, sharp enough to shave with, if you were braver than me."],
  alan_look_sardine: ['alan', "One sardine, wrapped in newspaper. The best bribe in Lisbon."],
  alan_look_lantern: ['alan', "Tomás's lantern. The same one, I think. Higher than he did."],

  // ================================================================ HINTS (Inês, "What now?")
  ines_hint_machine: ['ines', "The light's blinking, Alan. That's the machine's way of saying 'Alan'."],
  ines_hint_desk: ['ines', "He only sleeps there because the lamp's warm. Like you."],
  ines_hint_key: ['ines', "Your grandfather hid everything where he made his coffee. Start with the sugar."],
  ines_hint_police: ['ines', "Rui called you. Go to the Judiciária. Take the tram, not your time."],
  ines_hint_sketch: ['ines', "If they won't let you take it, draw it. You used to draw on everything."],
  ines_hint_show: ['ines', "Show me what you drew, then."],
  ines_hint_song: ['ines', "She said not sober and not alone. You can solve one of those with money."],
  ines_hint_amalia: ['ines', "Go and see Dona Amália. Be charming. Or at least be quiet."],
  ines_hint_1955: ['ines', "Amália said nineteen fifty-five. Rui keeps the city's old sins in his filing cabinet."],
  ines_hint_drawer: ['ines', "Salt is just stubborn water, Alan. Make it wet again."],
  ines_hint_threads: ['ines', "You've got a key to a dead man's shop and a policeman's mother. Pick one."],
  ines_hint_dark: ['ines', "Amália left matches on the bar. Even you can find a match in a tavern."],
  ines_hint_tide: ['ines', "A tide clock with no key, and you're carrying a key to everything your grandfather owned."],
  ines_hint_convent: ['ines', "The song said a church that prays without a roof. That's the Carmo. Go and see what the stone is crying about."],
  ines_hint_stone: ['ines', "Salt comes off with water. Even you know that. Holy water, if you can't find any other kind."],
  ines_hint_wheel: ['ines', "Sing it to yourself. How many times did she say?"],
  ines_hint_order: ['ines', "Tomás said the Sé. Go and talk to a deaf man about bells. Write it down for him."],
  ines_hint_theft: ['ines', "He'll notice the velvet. You need something that weighs what it weighs."],
  ines_hint_case: ['ines', "Ferreira kept spare keys. Lacerda's shop is full of things Ferreira made."],
  ines_hint_ch3_done: ['ines', "Cais do Sodré, Alan. The Maria Fé. Twenty-five past six, and the river doesn't wait for booksellers."],

  // ================================================================ FAILED USES
  alan_fail_01: ['alan', "I could, but then I'd have to explain it to Inês."],
  alan_fail_02: ['alan', "That's not how anything works. I checked; I sell the manuals."],
  alan_fail_03: ['alan', "Interesting idea. Wrong, but interesting. Like my twenties."],
  alan_fail_04: ['alan', "No. And I say that as a man who has said yes to a lot of bad ideas."],
  alan_fail_05: ['alan', "If that worked, someone would have done it already. Probably my grandfather."],
  alan_fail_06: ['alan', "I'm improvising, not hallucinating."],
  alan_fail_07: ['alan', "Grandfather would have known what to do with that. I know what not to do."],
  alan_fail_08: ['alan', "Those two things have nothing to say to each other. Like me at a wedding."],
  alan_fail_09: ['alan', "Tempting. Pointless, but tempting."],
  alan_fail_10: ['alan', "Even Pessoa would look at me funny for that, and he sleeps in a bookshop."],
  alan_fail_look: ['alan', "Nothing special about it. Which makes two of us."],
  alan_fail_take: ['alan', "I don't need that. I barely need half of what I've got."],
  alan_fail_use: ['alan', "That won't do anything. I know the feeling."],
  alan_fail_talk: ['alan', "It's not much of a conversationalist. Still better than my last date."],
  alan_fail_lacerda_item: ['alan', "I'm not giving him anything he can use. Except, possibly, a reason."],
  alan_fail_ze_item: ['alan', "He doesn't want that. He wants me off his boat."],
  alan_fail_abilio_item: ['alan', "He can't hear me, and he certainly can't hear that."],
  alan_fail_ines_item: ['alan', "She'd only correct my history and give it back."],
  alan_fail_rui_item: ['alan', "Offering evidence to a policeman. That's how they get you."],

  // ---- v2.1: Inês's opening, more to talk about
  alan_intro_3: ['alan', "[yawning] Or both. It's been that kind of decade."],
  ines_intro_3: ['ines', "And there's been another one. A fishwife in Madragoa. Door locked, windows shut. Drowned in her own bed."],
  alan_intro_4: ['alan', "Must have been a very small wave."],
  ines_intro_4: ['ines', "And the rent is due on Friday. So play your messages, and then try selling a book. Any book."],
  alan_ask_ines_fog: ['alan', "Has the fog ever done this before?"],
  ines_fog: ['ines', "Not in my lifetime. Nine days. The trams run with their lights on at noon, and the fishermen won't take the boats out. My grandmother would have said the river is sulking."],
  alan_ask_ines_shop: ['alan', "How's business?"],
  ines_shop: ['ines', "Two customers this week. One wanted directions, the other wanted the toilet. I sold him a map."],
  alan_ask_ines_drowned: ['alan', "These drownings. What do the papers say?"],
  ines_drowned: ['ines', "Nothing useful. 'A tragic accident.' Three tragic accidents, all in bed, all in dry rooms, all with salt water in their lungs. Your friend Rui is quoted. He says 'no comment' very eloquently."],
  // ---- Lino behind the bar
  lino_sell: ['lino', "Ginjinha? For you, menino, the good bottle. Two coins. Your grandfather never paid in his life, so you're settling a very old tab."],
  lino_poured: ['lino', "With the cherry. Always with the cherry."],
  // ---- the finale, re-paced
  lacerda_read_1: ['lacerda', "[muttering hungrily, turning pages] Ferreira... Bastos... Coutinho... and there you are, Joaquim. Every line."],
  lacerda_read_2: ['lacerda', "[whispering, delighted] Ah. So that is where you hid them."],
  lacerda_drag: ['lacerda', "[terrified, screaming] No... no! It's holding me! Sanchez! Your hand! Give me your hand!"],
  alan_no_hand: ['alan', "[quietly] You told me yourself. Be patient."],
  // ---- easter egg: a bath at the Lavadouro
  alan_bath_1: ['alan', "Nine days in this fog. I smell like a wet dog that's been reading poetry."],
  celeste_bath_1: ['celeste', "[shrieking] Ó menino! Put that away! This is a washhouse, not a bathhouse!"],
  alan_bath_2: ['alan', "Same water. Better company."],
  narr_bath: ['narr', "Dona Celeste would tell this story at every funeral in the Alfama for the next thirty years. It improved every time."],
  alan_bath_3: ['alan', "[cheerful] Clean as a hymn book. Nobody tell Inês."],
  celeste_bath_2: ['celeste', "[muttering] His grandfather did exactly the same thing in nineteen sixty. Same tank."],
  // ---- easter eggs: Alan flirts
  alan_flirt_cop_1: ['alan', "Officer. Do they issue those shoulders with the uniform, or did you bring your own?"],
  phone_flirt_1: ['phone', "[flustered] Sir, I'm on the phone. With my mother."],
  alan_flirt_cop_2: ['alan', "[admiring, patting his chest] Solid. Like a good oak bookcase. Tell her she raised a fine young man."],
  phone_flirt_2: ['phone', "[into the phone, embarrassed] Mãe? I'll call you back."],
  rui_flirt: ['rui', "[growling] Sanchez. Stop feeling up my constable and go and read your evidence."],
  alan_flirt_guitar_1: ['alan', "That's a beautiful instrument. Twelve strings, and you know exactly where every one of them is."],
  guitar_flirt_1: ['guitar', "[smooth, amused] It's all in the fingers, senhor. Thirty years of practice."],
  alan_flirt_guitar_2: ['alan', "Do you give lessons? Private ones?"],
  guitar_flirt_2: ['guitar', "[laughs] Tuesdays. Bring a bottle, and a bigger tip."],
  amalia_flirt: ['amalia', "[dry] Menino. Leave my guitarist alone. He has to play in tune tonight."],
  // ============================================ gameplay audit: state-aware responses
  alan_key_desk_first: ['alan', "Not yet. This is Grandfather's desk key, and I still haven't opened his drawer with it."],
  alan_bag_draw: ['alan', "Rui won't let me take it. Nobody said anything about drawing it, though."],
  alan_machine_coin: ['alan', "It wants a coin. Everything in this building wants something from me."],
  alan_desk_usekey: ['alan', "I've got the key in my pocket. Might help to actually use it."],
  alan_drawer_stuck: ['alan', "Stuck fast. Something's holding it shut, and it isn't the lock."],
  alan_phone_later: ['alan', "Nobody to ring. Rui knows where to find me, and he will."],
  narr_look_lamp_off: ['narr', "Grandfather's banker's lamp, dark for the first time since the funeral. The cat has lodged a complaint."],
  narr_look_machine_heard: ['narr', "The answering machine. Its one message has been heard, and the red light has finally stopped nagging."],
  narr_look_desk_open: ['narr', "Grandfather's desk, unlocked at last. The drawer gave up its ledger and kept the peppermint."],
  celeste_tile_again: ['celeste', "I've told you what I know about the bronze, menino. The rest is the river's business."],
  celeste_file_again: ['celeste', "I've said what I'll say about fifty-five. Don't make an old woman say it twice."],
  ines_hint_file: ['ines', "Celeste was at the lavadouro in fifty-five. Show her the case file."],
  ines_hint_matches: ['ines', "The workshop is dark and you've got matches in your pocket. Light something, Alan."],
  alan_ring_first: ['alan', "Before I go anywhere, I ring Inês. The phone box is right there, and she's been waiting all afternoon."],
  tomas_pray: ['tomas', "[quietly] Go, my son. I will be here, praying, until the bell is quiet."],
  alan_blood_later: ['alan', "Blood on the bronze. Not yet. I'd like to keep mine on the inside until it's actually needed."],
  ines_hint_ferreira: ['ines', "Celeste has told you her part. Now Ferreira's workshop. You've got his key."],

  // ============================================ playtest round: quay after the boat, washhouse after the bath, greetings
  ze_river_2: ['ze', "[low, a half smile] And if you need me on you again... you know where I moor."],
  alan_river_2: ['alan', "[flustered] Noted. Strictly for... maritime emergencies."],
  celeste_after_hello: ['celeste', "[knowing] Menino. You were on that boat a long while. The Maria Fé was rocking harder than the river, and the river is flat as a plate."],
  alan_after_celeste: ['alan', "[flustered] Below decks. Heavy weather. Very... localised."],
  celeste_after_laugh: ['celeste', "[laughs] Localised. I'll tell the coastguard."],
  alan_ask_ze_ok: ['alan', "Is Zé all right?"],
  celeste_after_ze: ['celeste', "He's whistling. Zé hasn't whistled since his mother died. Whatever you did down there, menino, you did it properly."],
  alan_after_ze: ['alan', "[flustered] I bailed. Mostly I bailed."],
  fish_after: ['fish', "[loud, delighted] Browsing again, menino? You browsed that boat for half an hour! The whole quay heard the hull knocking!"],
  alan_after_fish: ['alan', "[flustered] It's an old boat. It creaks."],
  mender1_after: ['mender1', "[weathered, slow] Forty years on this quay. Never seen a boat rock like that on a flat tide."],
  mender2_after: ['mender2', "[gruff, amused] Still in my light, bookseller. But sit down. You've earned it."],
  ines_hello_2: ['ines', "Back again? Talk while I shelve."],
  ines_hello_3: ['ines', "Yes, Alan?"],
  ines_hello_4: ['ines', "What is it this time?"],
  washer1_bath_1: ['washer1', "[giggling] Ai, did you see that, Graça? The bookseller's built like the Sé!"],
  washer2_bath_1: ['washer2', "[cackling] The Sé? Filha, more like the aqueduct. Long, and Roman."],
  alan_washers_1: ['alan', "[cheeky] Ladies, please. That was the cold water. Normally it's twice the cathedral."],
  washer1_bath_2: ['washer1', "[howling with laughter] Twice! Ai, Nossa Senhora!"],
  washer2_bath_2: ['washer2', "[wheezing] Come back on Thursday, menino. Thursday we do the big sheets!"],
  alan_washers_2: ['alan', "[flustered, retreating] Thursday. Right. I have to go and... alphabetise something."],
  washer2_bath_3: ['washer2', "[giggling] Thursday, menino! Bring the aqueduct!"],
  alan_tile_pocket: ['alan', "The tile's in my pocket. The bunk is just a wet blanket now. Like me at parties."],

  // ============================================ longer flirts, the visits, upstairs
  alan_flirt_cop_3: ['alan', "[impressed, squeezing his arm] Now that is a bicep. Do they make you carry the station to work every morning?"],
  phone_flirt_3: ['phone', "[into the phone, strangled] No, Mãe, nobody is... squeezing anything."],
  phone_flirt_4: ['phone', "[whispering, flustered] Senhor, please. My mother can hear you breathing."],
  alan_flirt_cop_4: ['alan', "[low, close] Then tell her you're in very good hands."],
  guitar_flirt_3: ['guitar', "[low, teasing] You've been watching my hands all evening, senhor. Most men watch Amália."],
  alan_flirt_guitar_3: ['alan', "[caught out] Amália has wonderful... hands. Also."],
  guitar_flirt_4: ['guitar', "[softly] Come. Give me your fingers. Here. And here. Gently... it answers if you're gentle."],
  alan_flirt_guitar_4: ['alan', "[breathless] I think it's... answering."],
  phone_visit_1: ['phone', "[shy] Senhor Sanches. Boa tarde. I was... passing. On patrol. In the fog."],
  ines_visit_cop: ['ines', "[dry] Passing. Through a door with a bell on it. Good afternoon, officer."],
  phone_visit_2: ['phone', "[too quickly] I came about a book! On bookcases. Oak ones. Very... solid ones."],
  alan_visit_cop: ['alan', "[flustered] The oak monograph! Of course. It's upstairs, in my room, with the other... reference works. Shall we, Officer? We have things to discuss."],
  guitar_visit_1: ['guitar', "[strolling in, grinning] Boa tarde. I was told the best stock in Lisbon is kept in the back."],
  ines_visit_guitar: ['ines', "[dry] Upstairs, actually. He keeps everything upstairs."],
  guitar_visit_2: ['guitar', "[to Alan, smiling] Then I'll need the private tour. Tuesday came early this week."],
  alan_visit_guitar: ['alan', "[flustered, to Inês] He's tuning the... piano. Upstairs. It's very out of tune. We have things to discuss."],
  ines_visit_after: ['ines', "[deadpan] Discuss things. Of course. I'll mind the shop. Again."],
  phone_room_1: ['phone', "[nervous, quiet] I've never... I mean, not with a man who sells books."],
  alan_room_cop_1: ['alan', "[softly] Then let me do the talking. For once in my life, I'll keep it short."],
  phone_room_2: ['phone', "[breathless] Senhor..."],
  alan_room_cop_2: ['alan', "[into his neck] Alan. It's Alan."],
  narr_room_cop: ['narr', "The bookshelf had held Camões and Pessoa and forty years of dust. It had never held a policeman. Three volumes of Eça de Queirós gave their lives that afternoon, and nobody went back for them."],
  phone_room_3: ['phone', "[dazed, from the floor] I should... radio in."],
  alan_room_cop_3: ['alan', "[smiling] Tell them the suspect was very cooperative."],
  guitar_room_1: ['guitar', "[laughing] Your shirt's on inside out, bookseller."],
  alan_room_guitar_1: ['alan', "[grinning] Not for long."],
  narr_room_guitar: ['narr', "The iron bed had survived a revolution, two floods and Alan's grandfather. It very nearly did not survive Duarte. Downstairs, Inês turned the radio up and sold three dictionaries out of spite."],
  guitar_room_3: ['guitar', "[lazy, content] Tuesdays, then?"],
  alan_room_guitar_2: ['alan', "[happy] And Thursdays. I want to learn the scales."],
  alan_room_cop_4: ['alan', "[low, amused] Too many buttons on these uniforms."],
  phone_room_4: ['phone', "[breathless laugh] Regulation."],
  guitar_room_4: ['guitar', "[cracking his belt like a whip] Ha! First belt off wins, bookseller."],
  alan_room_guitar_3: ['alan', "[grinning] Best of three, then. Trousers."],
  // the handcuffs
  alan_room_cop_5: ['alan', "[low, pinning his wrist to the shelf] Hands where I can see them, Officer."],
  phone_room_5: ['phone', "[squeaking] That's... that's my line."],
  phone_room_6: ['phone', "[staring, hoarse] Is that... is that allowed?"],
  alan_room_cop_6: ['alan', "[smirking] Arrest me."],
  alan_room_cop_7: ['alan', "[tugging at the duty belt] And what's all this for?"],
  phone_room_7: ['phone', "[faintly] Equipment."],
  phone_after_1: ['phone', "[rattling the cuff] Alan. The key. You are holding the key."],
  alan_after_1: ['alan', "[pocketing it, grinning] Ten minutes. Don't go anywhere, Officer."],
  phone_after_2: ['phone', "[to the empty room, very small] ...Regulation."],
  guitar_room_5: ['guitar', "[grabbing his lapels] Shall we tune up, bookseller?"],
  alan_room_guitar_4: ['alan', "[grabbing back] You first."],
  alan_room_guitar_5: ['alan', "[whistling, clapping] Encore!"],
  guitar_room_6: ['guitar', "[doubled over laughing] You look ridiculous!"],
  alan_room_guitar_6: ['alan', "[swinging his jeans overhead] Ridiculous, and winning!"],
  guitar_room_2: ['guitar', "[breathless, laughing] Race you to the bed."],
  alan_room_guitar_7: ['alan', "[crouching, patting his shoulder] Why race? Hop on. Express service."],
  guitar_room_7: ['guitar', "[whooping] Giddy up, bookseller!"],
  guitar_after_1: ['guitar', "[calling after him, strumming] Bring coffee! And a rhyme for 'bookseller'!"],
  alan_room_cop_8: ['alan', "[peering round him, appreciative] Officer Teixeira. That is an illegally good arse. I'm going to have to confiscate it."],
  phone_room_8: ['phone', "[mortified, tiny] ...Is there a form?"],
  phone_room_9: ['phone', "[staring down, voice cracking] Senhor... is that even legal?"],
  alan_room_cop_9: ['alan', "[smug] Licensed and registered, Officer."],
  guitar_room_8: ['guitar', "[glancing down, unbothered, eyebrows up] Ora, ora. That's not a guitar, bookseller. That's a double bass."],
  alan_room_guitar_8: ['alan', "[grinning] Unabridged edition."],
  guitar_room_9: ['guitar', "[lazy, purring] Relax. I know exactly how to play your instrument."],
  ines_back_cop: ['ines', "[not looking up from the ledger, dry] The officer's radio has asked for him eleven times. I said he was assisting with a monograph. Is he still assisting?"],
  alan_back_cop: ['alan', "[smoothing his hair, far too casual] Deeply. He's become very... attached to the subject."],
  ines_back_guitar: ['ines', "[deadpan] So the piano's in tune now? Strange. We don't own a piano."],
  alan_back_guitar: ['alan', "[flustered, then rallying] It's a... very modern piano. Upright."],
  alan_cuff_1: ['alan', "[low, commanding] Officer Teixeira. You have the right to remain silent."],
  phone_cuff_1: ['phone', "[squeaking] I... don't think I can."],
  alan_cuff_2: ['alan', "[wicked] Then we'll do this the hard way. Wrists."],
  narr_cuff: ['narr', "Some time later, when the lamp had been knocked over twice and the bed had walked six inches towards the window, Officer Teixeira asked a reasonable question."],
  phone_cuff_2: ['phone', "[sheepish] Alan? Where's the key?"],
  alan_cuff_3: ['alan', "[pause] The key. Yes. The key is... somewhere very safe."],
  phone_cuff_3: ['phone', "[rising panic] How safe?"],
  alan_cuff_4: ['alan', "[muffled, from under the covers] Extremely safe. Don't move."],
  phone_cuff_4: ['phone', "[deadpan] Where would I go?"],
  ines_cuff: ['ines', "[calling up the stairs] Alan! There's a police radio squawking down here. The station wants to know where their officer is."],
  alan_cuff_5: ['alan', "[calling down, strangled] Tell them he's... helping with enquiries!"],
  phone_cuff_5: ['phone', "[very small voice] Alan. It's in my hat."],
  alan_cuff_6: ['alan', "[pause] Of course it is. The one thing you kept on."],
};
